# Encontros 31 a 40: leitura e interpretação de textos.
from base import M, A, VF, C, T, E

B = 'Leitura e interpretação'
FONTE = 'Texto elaborado para esta atividade.'

E(31, B, 'Tema, assunto e ideia central do texto',
  aquecimento='Pense em um filme ou série de que você gosta: em uma palavra, do que ele fala? E, em uma frase, o que ele quer mostrar sobre isso?',
  quadro=['# Assunto: do que o texto fala',
    '- É o “quê” de modo amplo; cabe em uma palavra ou expressão curta. Ex.: o celular; a água; o trabalho.',
    '- Muitos textos podem ter o mesmo assunto e dizer coisas bem diferentes sobre ele.',
    '# Tema: o recorte do assunto',
    '- É a delimitação: o que, exatamente, se discute sobre o assunto. Ex.: o uso do celular durante as aulas.',
    '- Assunto: futebol. Tema: o racismo nos estádios de futebol. (o tema é mais específico)',
    '# Ideia central: a mensagem principal',
    '- É o que o autor quer mostrar sobre o tema, em uma frase completa (com verbo).',
    '- Ex.: “O celular atrapalha a atenção dos alunos quando é usado sem regras na aula.”',
    '- Pergunta-chave: o que o autor quer mostrar, defender ou contar sobre esse assunto?',
    '- Resumo: assunto (palavra) → tema (expressão com recorte) → ideia central (frase).',
    '# Onde procurar pistas',
    '- Título: costuma antecipar o assunto ou o tema (mas pode ser irônico ou criar suspense).',
    '- Palavras-chave: termos que se repetem ou são retomados por sinônimos ao longo do texto.',
    '- Tópico frasal: frase (em geral a primeira) que resume a ideia do parágrafo; as outras explicam, exemplificam ou detalham.',
    '- Introdução e conclusão: nos textos argumentativos, a ideia central costuma aparecer no início e ser retomada no fim.',
    '# Passo a passo',
    '- 1) Leia o texto inteiro. 2) Marque as palavras-chave. 3) Resuma cada parágrafo em uma linha.',
    '- 4) Junte os resumos e pergunte: que ideia está presente em TODOS os parágrafos? Essa é a ideia central.',
    '# Mais exemplos',
    '- Assunto: leitura. Tema: as bibliotecas públicas nos bairros. Ideia central: bibliotecas de bairro aproximam os livros de quem não pode comprá-los.',
    '- Assunto: alimentação. Tema: o consumo de ultraprocessados por crianças. Ideia central: o excesso desses produtos prejudica a saúde infantil.',
    '# Fique atento',
    '- A ideia central não é um detalhe, um exemplo ou um dado do texto: ela precisa “abraçar” o texto todo.',
    '- Ela também não é a sua opinião sobre o assunto: é o que o AUTOR diz.',
    '- Alternativas muito amplas (só o assunto) ou muito estreitas (só um parágrafo) costumam estar erradas.',
    '- Na redação do ENEM, falar só do assunto geral, sem o recorte do tema, é tangenciar o tema e derruba muito a nota.'],
  q=[M('“A água” é o assunto de um texto. Qual alternativa apresenta um TEMA (um recorte) desse assunto?',
       ['O desperdício de água nas cidades brasileiras', 'A natureza e todos os seus recursos', 'Os líquidos e os recursos do planeta', 'A água e tudo o que se relaciona a ela'], 0),
     M('A ideia central de um texto deve ser expressa:',
       ['em uma frase completa que resume o que o autor quer mostrar', 'em uma única palavra, como “saúde” ou “escola”', 'pelo exemplo mais curioso que aparece no texto', 'pela opinião do leitor sobre o assunto do texto'], 0),
     A('Organize do mais amplo para o mais específico: “o uso do celular durante as aulas” – “tecnologia” – “o celular”.',
       'tecnologia → o celular → o uso do celular durante as aulas.'),
     T('Em muitos bairros, terrenos abandonados estão virando hortas comunitárias. Onde antes havia lixo e mato, agora crescem alface, couve e temperos cuidados pelos próprios moradores.\n'
       'O primeiro ganho está na mesa. As famílias passam a ter verduras frescas e baratas, colhidas a poucos passos de casa.\n'
       'A horta também ensina. Crianças descobrem de onde vem a comida, e moradores mais velhos repassam técnicas de plantio que aprenderam na roça.\n'
       'O ganho mais valioso, porém, é o convívio. Vizinhos que mal se cumprimentavam passam a dividir ferramentas, sementes e conversas. Por isso, apoiar as hortas comunitárias é mais do que cuidar de canteiros: é cultivar a vida em comunidade.',
       fonte=FONTE, titulo='Hortas que unem vizinhos', para=4),
     A('Em uma palavra ou expressão curta, qual é o assunto do texto?', 'Hortas comunitárias.'),
     M('Qual frase expressa melhor a ideia central do texto?',
       ['As hortas comunitárias trazem vários benefícios aos bairros, e o maior deles é o convívio entre vizinhos.',
        'Os terrenos abandonados acumulam lixo e mato em muitos bairros das cidades.',
        'Os moradores mais velhos conhecem técnicas de plantio que aprenderam na roça.',
        'As prefeituras deveriam transformar todas as praças da cidade em hortas.'], 0),
     A('Copie o tópico frasal do parágrafo que começa com “O primeiro ganho”.', '“O primeiro ganho está na mesa.”'),
     M('O título “Hortas que unem vizinhos” antecipa:',
       ['o benefício que o autor considera o mais importante', 'um problema que o texto pretende denunciar', 'uma informação que o texto contradiz no final', 'um detalhe que não volta a aparecer no texto'], 0),
     T('Muitos adolescentes levam o celular para a cama e ficam conectados até tarde. O problema não é apenas o tempo de sono perdido. A luz da tela e as notificações deixam o cérebro em alerta, o que torna o sono mais leve e menos reparador. No dia seguinte, aparecem o cansaço, a irritação e a dificuldade de concentração. Deixar o aparelho longe da cama por uma hora antes de dormir é um hábito simples que ajuda a descansar melhor.',
       fonte=FONTE, titulo='Desligar para descansar', para=3),
     M('Qual alternativa indica corretamente o assunto e o tema do texto?',
       ['Assunto: o sono. Tema: o efeito do celular no sono dos adolescentes.',
        'Assunto: o efeito do celular no sono dos adolescentes. Tema: o sono.',
        'Assunto: a escola. Tema: a falta de concentração nas aulas.',
        'Assunto: a tecnologia. Tema: as vantagens das redes sociais.'], 0),
     M('Segundo o texto, o problema do celular na cama “não é apenas o tempo de sono perdido” porque:',
       ['a luz e as notificações também deixam o sono mais leve e menos reparador', 'os adolescentes deixam de fazer as tarefas da escola', 'o aparelho pode esquentar e estragar durante a noite', 'as redes sociais espalham notícias falsas durante a noite'], 0),
     A('Copie a frase do texto que apresenta uma solução para o problema.',
       '“Deixar o aparelho longe da cama por uma hora antes de dormir é um hábito simples que ajuda a descansar melhor.”', 2),
     M('Leia: “A bicicleta é um meio de transporte barato. Não gasta combustível, ocupa pouco espaço e ainda melhora a saúde de quem pedala. Por isso, as cidades deveriam investir em ciclovias.” A ideia central desse parágrafo é:',
       ['a bicicleta traz vantagens e, por isso, merece investimento em ciclovias', 'a bicicleta não gasta nenhum tipo de combustível', 'quem pedala todos os dias melhora a própria saúde', 'as cidades brasileiras têm pouco espaço nas ruas'], 0),
     M('Um aluno disse que a ideia central de um texto sobre reciclagem era “reciclagem”. O erro dele foi:',
       ['confundir a ideia central com o assunto', 'confundir o assunto com o título', 'escolher um detalhe do texto', 'dar a própria opinião sobre o texto'], 0),
     M('Qual título combina melhor com um texto cuja ideia central é “a prática regular de exercícios melhora o humor e a disposição”?',
       ['Movimento que faz bem à cabeça', 'A história das Olimpíadas', 'Como escolher um tênis de corrida', 'Os perigos das academias'], 0),
     C('Associe cada termo à sua definição:',
       [('assunto', 'do que o texto fala, de modo amplo'), ('tema', 'o recorte específico do assunto'),
        ('ideia central', 'o que o autor quer mostrar, em uma frase'), ('tópico frasal', 'a frase que resume a ideia do parágrafo'),
        ('palavras-chave', 'termos que se repetem e indicam o assunto')]),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('O título sempre revela a ideia central do texto.', False),
         ('Um mesmo assunto pode gerar muitos temas diferentes.', True),
         ('A ideia central deve valer para o texto inteiro, e não só para um parágrafo.', True),
         ('Um exemplo citado no texto pode ser a sua ideia central.', False),
         ('Palavras repetidas ou retomadas por sinônimos ajudam a descobrir o assunto.', True)]),
     A('Para o assunto “redes sociais”, escreva dois temas (recortes) diferentes.',
       'Ex.: a exposição de crianças nas redes sociais; a influência das redes sociais na autoestima dos jovens.', 2),
     A('Escreva um tópico frasal para um parágrafo sobre a importância de beber água.',
       'Resposta pessoal. Ex.: Beber água ao longo do dia é essencial para o bom funcionamento do corpo.', 2),
  ],
  producao='Escolha um assunto do seu dia a dia (transporte, alimentação, lazer, trabalho...). Escreva o assunto e um tema (recorte) dele. Depois, escreva um parágrafo de 6 a 8 linhas que comece com um tópico frasal claro e desenvolva essa ideia com explicações e exemplos.')

E(32, B, 'Informação explícita e implícita: inferência, pressuposto e subentendido',
  aquecimento='Se alguém diz “Parei de fumar”, o que sabemos sobre o passado dessa pessoa, mesmo sem ela contar? E se um colega diz “Que calor aqui dentro!” olhando para a janela fechada, o que ele pode estar querendo?',
  quadro=['# Explícito x implícito',
    '- Explícito: o que está escrito com todas as letras no texto. Ex.: “A loja fecha às 18h.”',
    '- Implícito: o que não está escrito, mas pode ser compreendido a partir de pistas do texto e do contexto.',
    '# Inferência: concluir a partir de pistas',
    '- Inferir é tirar uma conclusão lógica com base no que o texto mostra.',
    '- Ex.: “Ele entrou com o guarda-chuva pingando.” → Estava chovendo lá fora.',
    '- A inferência precisa de apoio no texto: não é chute nem imaginação.',
    '# Pressuposto: ideia garantida por uma palavra da frase',
    '- “Paulo ainda mora com os pais.” → Ele já morava com os pais antes.',
    '- “Ana deixou de comer carne.” → Antes, ela comia carne.',
    '- “O ônibus voltou a atrasar.” → Ele já tinha atrasado antes.',
    '- “Ela já não trabalha aqui.” → Antes, ela trabalhava aqui.',
    '- “Até o professor errou a conta.” → Outros erraram, e não se esperava que o professor errasse.',
    '- “Eu também passei de ano.” → Outra pessoa passou de ano.',
    '- Marcadores comuns: ainda, já, também, até, deixar de, parar de, voltar a, continuar, de novo, outra vez.',
    '- Teste: o pressuposto continua valendo na negação e na pergunta. “Ana não deixou de comer carne.” / “Ana deixou de comer carne?” → Ela comia carne.',
    '# Subentendido: insinuação que depende do contexto',
    '- É uma ideia sugerida, que o ouvinte deduz pela situação; quem fala pode negar que quis dizer aquilo.',
    '- “Está frio aqui, né?” (dito perto da janela aberta) → Feche a janela.',
    '- “Nossa, já são onze horas!” (dito pelo dono da casa à visita) → Está na hora de ir embora.',
    '- “Meu celular está quase sem bateria...” → Você me empresta o carregador?',
    '# Pressuposto x subentendido',
    '- Pressuposto: está preso a uma palavra ou expressão da frase; não dá para negá-lo sem contradição.',
    '- Subentendido: depende de quem fala, para quem, onde e quando.',
    '# Fique atento',
    '- “O texto permite inferir” pede uma conclusão APOIADA no texto, e não algo que apenas poderia ser verdade.',
    '- Desconfie de alternativas que acrescentam informações sem pistas no texto: isso é extrapolar.',
    '- Charges, tirinhas e propagandas costumam trabalhar com o implícito: é preciso “ler nas entrelinhas”.'],
  q=[M('Qual frase traz uma informação EXPLÍCITA sobre o horário de funcionamento da biblioteca?',
       ['A biblioteca abre às 8h e fecha às 17h.', 'Chegue cedo, porque a biblioteca costuma lotar.', 'Ontem a biblioteca já estava fechada quando cheguei.', 'Os funcionários da biblioteca saem antes de anoitecer.'], 0),
     M('Na frase “Carla voltou a estudar inglês”, qual informação está PRESSUPOSTA?',
       ['Carla já tinha estudado inglês antes', 'Carla vai morar no exterior em breve', 'Carla gosta mais de inglês do que de espanhol', 'Carla nunca tinha estudado uma língua estrangeira'], 0),
     A('Que informação está pressuposta em “Meu pai parou de trabalhar à noite”?', 'Antes, o pai trabalhava à noite.'),
     T('Quando Dona Lúcia abriu a porta, Marcos estava encharcado, com o tênis cheio de lama e o guarda-chuva quebrado na mão. Ela não disse nada: foi buscar uma toalha e colocou água para esquentar. Marcos olhou o relógio da cozinha e suspirou. A prova de recuperação tinha começado havia vinte minutos, e a escola ficava do outro lado da cidade. Pegou o celular, viu que estava sem bateria e se jogou no sofá.',
       fonte=FONTE, titulo='Dia de prova', para=4),
     M('O texto NÃO diz, mas permite inferir que:',
       ['Marcos tinha enfrentado chuva no caminho', 'Marcos estava com febre e muito doente', 'Dona Lúcia estava brava com Marcos', 'a escola tinha cancelado a prova'], 0),
     M('A atitude de Dona Lúcia (buscar uma toalha e esquentar água) permite inferir que ela:',
       ['se preocupou em cuidar de Marcos', 'queria que Marcos fosse embora logo', 'estava atrasada para o trabalho', 'não conhecia Marcos'], 0),
     M('Pelo trecho “A prova de recuperação tinha começado havia vinte minutos, e a escola ficava do outro lado da cidade”, conclui-se que Marcos:',
       ['provavelmente perderia a prova', 'já tinha feito a prova mais cedo', 'iria para a escola de carro', 'não precisava fazer a recuperação'], 0),
     A('Copie duas pistas do texto que mostram que Marcos tinha pegado chuva.',
       'Duas destas: “estava encharcado”; “com o tênis cheio de lama”; “o guarda-chuva quebrado na mão”.', 2),
     T('Na sala, Bruno jogava videogame quando a mãe chegou do trabalho.\n'
       '— Filho, você já arrumou o quarto?\n'
       '— Ainda não, mãe. Mas hoje eu lavei a louça!\n'
       '— Que bom. Pena que o lixo continua na porta da cozinha... E o caminhão passa daqui a pouco.\n'
       '— Tá bom, já entendi. Vou levar agora.',
       fonte=FONTE, titulo='Para bom entendedor...', para=4),
     M('A fala da mãe “Pena que o lixo continua na porta da cozinha... E o caminhão passa daqui a pouco” traz um SUBENTENDIDO. Qual?',
       ['A mãe quer que Bruno leve o lixo para fora', 'A mãe vai sair para alcançar o caminhão', 'A mãe acha que Bruno não lavou a louça', 'A mãe quer que Bruno vá estudar'], 0),
     M('Na mesma fala, a palavra “continua” pressupõe que:',
       ['o lixo já estava na porta da cozinha antes', 'o lixo foi colocado ali agora há pouco', 'o caminhão do lixo não passa naquele bairro', 'Bruno já tinha levado o lixo para fora'], 0),
     M('Como Bruno percebeu o que a mãe queria, mesmo sem um pedido direto?',
       ['Pelo contexto: ele deduziu a insinuação a partir da situação', 'Porque a mãe deu uma ordem com todas as letras', 'Porque a palavra “lixo” sempre indica uma ordem', 'Porque ele leu um bilhete deixado pela mãe'], 0),
     A('Bruno responde “Ainda não”. O que a expressão “ainda não” pressupõe sobre a arrumação do quarto?',
       'Que o quarto não foi arrumado até agora, mas a arrumação é esperada (é uma tarefa pendente, que vai ser feita).', 2),
     M('Em qual frase há uma palavra ou expressão que indica que algo era diferente no passado?',
       ['Joana deixou de usar o elevador.', 'Joana mora no décimo andar.', 'Joana usa o elevador todos os dias.', 'Joana sobe de escada à noite.'], 0),
     M('Um cliente diz ao garçom: “Faz quarenta minutos que pedi a minha pizza...”. O subentendido dessa fala é:',
       ['uma reclamação pela demora, para que a pizza chegue logo', 'um elogio ao sabor da pizza servida no restaurante', 'a informação de que ele chegou cedo ao restaurante', 'a vontade de experimentar outro sabor de pizza'], 0),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('Informação explícita é a que está escrita claramente no texto.', True),
         ('Inferir é imaginar livremente o que poderia acontecer na história.', False),
         ('O pressuposto pode ser marcado por palavras como “ainda”, “já”, “deixou de” e “voltou a”.', True),
         ('O subentendido depende da situação de comunicação.', True),
         ('Quem faz uma insinuação nunca pode negar que quis dizer aquilo.', False)]),
     C('Associe cada frase ao que está implícito nela:',
       [('“Ele já não fuma.”', 'antes ele fumava'), ('“Até a diretora dançou na festa.”', 'não se esperava que ela dançasse'),
        ('“Você vai sair com esse casaco?”', 'insinua que o casaco não é adequado'), ('“O carro quebrou outra vez.”', 'o carro já tinha quebrado antes')]),
     A('Reescreva “Ricardo está desempregado” acrescentando uma palavra que crie o pressuposto de que ele já estava desempregado antes.',
       'Ricardo ainda está desempregado. / Ricardo continua desempregado.'),
     A('Crie uma frase com subentendido para pedir, sem dizer diretamente, que alguém abaixe o volume da música.',
       'Resposta pessoal. Ex.: “Nossa, não consigo nem ouvir o que você está falando!”', 2),
  ],
  producao='Escreva um diálogo de 6 a 10 falas em que um dos personagens faz um pedido ou uma crítica sem dizer diretamente (subentendido). Use também pelo menos duas palavras que criem pressupostos (ainda, já, deixou de, voltou a, também, até) e sublinhe-as.')

E(33, B, 'Os três erros de interpretação: extrapolar, reduzir (restringir) e contradizer o texto',
  aquecimento='Leia em voz alta: “Alguns alunos da turma chegaram atrasados hoje por causa da chuva.” É correto concluir que “a turma toda chegou atrasada”? E que “os alunos dessa turma nunca são pontuais”? Por quê?',
  quadro=['# Interpretar é ficar dentro do texto',
    '- A resposta certa sempre pode ser “provada” com um trecho do texto. Se não há prova, desconfie.',
    '- Três erros clássicos nas provas: extrapolar, reduzir e contradizer.',
    '# 1. Extrapolação: ir além do texto',
    '- É afirmar o que o texto não disse: generalizar, opinar, inventar causas, consequências ou soluções.',
    '- Texto: “Alguns alunos faltaram por causa da chuva.” Extrapolação: “Os alunos dessa escola faltam muito.”',
    '- Sinais de alerta: sempre, nunca, todos, nenhum, único, apenas, totalmente, com certeza.',
    '- Também é extrapolar apresentar o seu conhecimento ou a sua opinião como se fossem do autor.',
    '# 2. Redução (restrição): ficar aquém do texto',
    '- É tomar a parte pelo todo: reduzir o sentido a um detalhe, a um exemplo ou a um só parágrafo.',
    '- Texto sobre as vantagens da bicicleta (saúde, economia e meio ambiente). Redução: “O texto mostra que pedalar emagrece.”',
    '- A alternativa reduzida costuma trazer algo verdadeiro, mas incompleto: não responde ao que foi pedido.',
    '# 3. Contradição: dizer o contrário do texto',
    '- É afirmar o oposto do que o texto diz. Ex.: o texto elogia uma lei, e a alternativa diz que ele a critica.',
    '- Cuidado com negações (não, nem, sem) e com palavras trocadas por antônimos.',
    '# Técnica da prova',
    '- 1) Leia o enunciado e veja o que ele pede: ideia central? uma informação? a opinião do autor?',
    '- 2) Para cada alternativa, volte ao texto e procure a “prova”: o trecho que confirma o que ela diz.',
    '- 3) Classifique: correta, extrapolação (foi além), redução (ficou só em uma parte) ou contradição (disse o oposto).',
    '# Mais exemplos',
    '- Texto: “Ler antes de dormir pode ajudar a relaxar.” Correta: ler pode ajudar a relaxar. Extrapolação: ler cura a insônia. Contradição: ler antes de dormir agita a pessoa.',
    '# Fique atento',
    '- “Pode”, “talvez”, “alguns” e “muitos” não são o mesmo que “sempre” e “todos”: respeite o grau de certeza do texto.',
    '- Uma informação verdadeira no mundo real pode estar errada na prova se o texto não diz aquilo.',
    '- Na dúvida entre duas alternativas, fique com a que tem prova no texto e responde exatamente à pergunta.'],
  q=[M('Afirmar algo que o texto NÃO disse, como uma generalização ou uma opinião própria, é:',
       ['extrapolar', 'reduzir', 'contradizer', 'resumir'], 0),
     M('Texto: “Muitos jovens usam as redes sociais para se informar.” A afirmação “Todos os jovens se informam apenas pelas redes sociais” é:',
       ['extrapolação', 'redução', 'contradição', 'interpretação correta'], 0),
     M('Texto: “O parque foi reformado e ganhou nova iluminação, quadras e brinquedos.” A afirmação “O parque continua sem iluminação” é:',
       ['contradição', 'extrapolação', 'redução', 'interpretação correta'], 0),
     T('Caminhar é uma das atividades físicas mais acessíveis que existem. Não exige equipamento caro nem matrícula em academia: basta um calçado confortável e um lugar seguro.\n'
       'Os benefícios vão além do corpo. Além de ajudar o coração e o controle do peso, a caminhada regular pode melhorar o humor e reduzir o estresse, segundo muitos estudos.\n'
       'No entanto, caminhar não é igualmente fácil para todos. Em muitos bairros, faltam calçadas, iluminação e segurança, o que afasta principalmente idosos e pessoas com deficiência.\n'
       'Por isso, incentivar a caminhada não depende só da força de vontade de cada um: depende também de cidades que cuidem de seus espaços públicos.',
       fonte=FONTE, titulo='Caminhar é para todos?', para=5),
     M('Qual alternativa expressa CORRETAMENTE a ideia central do texto?',
       ['Caminhar é acessível e faz bem, mas incentivar esse hábito também depende de cidades com espaços públicos adequados.',
        'Caminhar ajuda o coração e o controle do peso de quem pratica a atividade.',
        'Caminhar é a única atividade física capaz de reduzir o estresse das pessoas.',
        'Caminhar depende apenas da força de vontade e da disciplina de cada pessoa.'], 0),
     M('A expressão “pode melhorar o humor” indica que o autor:',
       ['apresenta o benefício como possibilidade, e não como garantia', 'garante que todos ficarão felizes ao caminhar', 'duvida que a caminhada traga algum benefício', 'critica quem prefere frequentar academias'], 0),
     M('A afirmação “Segundo o texto, os idosos não gostam de caminhar” é um caso de:',
       ['extrapolação, pois o texto fala em falta de calçadas, iluminação e segurança, e não em gosto',
        'redução, pois o texto trata somente dos idosos e de nenhum outro grupo',
        'contradição, pois o texto afirma que os idosos são os que mais caminham',
        'interpretação correta, pois o texto diz que os idosos se afastam da caminhada'], 0),
     A('Copie do texto o trecho que prova que caminhar não é igualmente fácil para todos.',
       '“Em muitos bairros, faltam calçadas, iluminação e segurança, o que afasta principalmente idosos e pessoas com deficiência.”', 2),
     A('Classifique cada afirmação sobre o texto com uma palavra do quadro. I. “Quem caminha todos os dias nunca fica estressado.” II. “Em muitos bairros, faltam condições seguras para caminhar.” III. “Segundo o texto, caminhar é caro e exige academia.” IV. “O texto trata apenas dos benefícios da caminhada para o coração.”',
       'I. extrapolação (o texto diz que a caminhada “pode” reduzir o estresse); II. correta; III. contradição; IV. redução (o texto também fala de humor, estresse e das condições das cidades).',
       3, banco=['correta', 'extrapolação', 'redução', 'contradição']),
     T('Uma escola pública do bairro Vila Nova inaugurou, na última segunda-feira, uma biblioteca montada pelos próprios estudantes. Os livros foram doados por moradores do bairro durante uma campanha de dois meses. A sala, que antes servia de depósito, foi pintada pelos alunos do 9º ano com a ajuda de alguns pais. Segundo a diretora, a biblioteca ficará aberta também aos sábados para a comunidade. Os estudantes já planejam criar um clube de leitura mensal.',
       fonte=FONTE, titulo='Estudantes inauguram biblioteca', para=4),
     M('Qual afirmação é uma EXTRAPOLAÇÃO do texto?',
       ['Desde a inauguração, as notas de todos os alunos melhoraram.', 'A sala da biblioteca antes servia de depósito.', 'A campanha de doação de livros durou dois meses.', 'Os estudantes planejam criar um clube de leitura.'], 0),
     M('Qual afirmação é uma CONTRADIÇÃO do texto?',
       ['A biblioteca ficará fechada aos sábados.', 'Os livros foram doados por moradores do bairro.', 'A biblioteca também atenderá a comunidade.', 'Alguns pais ajudaram a pintar a sala.'], 0),
     M('Um leitor resumiu o texto assim: “Moradores doaram livros para uma escola”. Esse resumo:',
       ['reduz o texto, pois deixa de fora o fato principal: a inauguração da biblioteca montada pelos estudantes',
        'extrapola o texto, pois os livros da biblioteca não foram doados por moradores',
        'contradiz o texto, pois a escola comprou os livros com o dinheiro de uma campanha',
        'resume corretamente o texto, pois apresenta todas as suas informações principais'], 0),
     A('Escreva uma afirmação que EXTRAPOLE o texto e explique por que ela vai além do que foi dito.',
       'Resposta pessoal. Ex.: “Todos os moradores do bairro adoram ler.” O texto só diz que moradores doaram livros; não fala do gosto de todos pela leitura.', 2),
     M('Texto: “Dormir bem melhora a memória, o humor e a imunidade.” Qual resumo é uma REDUÇÃO desse texto?',
       ['Dormir bem melhora a memória.', 'Dormir bem melhora a memória, o humor e as defesas do corpo.', 'Dormir bem cura todas as doenças.', 'Dormir bem piora o humor e a memória.'], 0),
     M('Texto: “Em algumas cidades, o transporte público gratuito aumentou o movimento no comércio.” A frase “O transporte gratuito resolve todos os problemas das cidades” é uma extrapolação porque:',
       ['generaliza um resultado observado em algumas cidades e exagera o seu efeito', 'repete exatamente o que o texto afirma', 'deixa de fora uma parte importante do texto', 'afirma o contrário do que o texto diz'], 0),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('A alternativa reduzida pode trazer uma informação verdadeira, mas incompleta.', True),
         ('Palavras como “sempre”, “todos” e “nunca” são sinais de alerta para a extrapolação.', True),
         ('Se uma informação é verdadeira no mundo real, ela está certa na prova de interpretação.', False),
         ('Contradizer o texto é afirmar o oposto do que ele diz.', True),
         ('Apresentar a opinião pessoal como se fosse do autor é uma leitura correta.', False)]),
     C('Texto: “Algumas praias do litoral ficaram impróprias para banho depois das chuvas, e a prefeitura pede que os banhistas consultem os boletins antes de entrar no mar.” Associe cada afirmação à sua classificação:',
       [('Todas as praias do Brasil estão poluídas.', 'extrapolação'),
        ('O texto apenas informa que choveu no litoral.', 'redução'),
        ('Depois das chuvas, todas as praias continuaram próprias para banho.', 'contradição'),
        ('Algumas praias ficaram impróprias, e os banhistas devem consultar os boletins.', 'leitura correta')]),
     A('Texto: “Alguns aplicativos de mensagens são usados para espalhar notícias falsas.” Reescreva a afirmação “Os aplicativos de mensagens só servem para espalhar notícias falsas” de modo que ela fique fiel ao texto.',
       'Alguns aplicativos de mensagens são usados para espalhar notícias falsas. (É preciso trocar “os” por “alguns” e retirar o “só”, que generalizam.)', 2),
  ],
  producao='Releia o texto “Caminhar é para todos?” e escreva um resumo de 5 a 8 linhas fiel a ele: sem extrapolar (não acrescente opiniões nem generalizações), sem reduzir (inclua todas as ideias principais) e sem contradizer. Depois, sublinhe a frase do seu resumo que apresenta a ideia central.')

E(34, B, 'Fato e opinião; o ponto de vista do autor',
  aquecimento='Ouça duas frases: “Hoje é sexta-feira.” e “Sexta-feira é o melhor dia da semana.” Qual delas dá para conferir no calendário? Qual depende do gosto de cada um?',
  quadro=['# Fato: o que pode ser verificado',
    '- Acontecimento ou dado que pode ser comprovado com documentos, medições, registros ou testemunhas.',
    '- Ex.: “A escola tem 600 alunos.” “Choveu ontem à tarde.” “O Brasil fica na América do Sul.”',
    '- Uma afirmação de fato pode até estar errada, mas sempre dá para checar.',
    '# Opinião: um juízo de valor',
    '- É a avaliação, a interpretação ou o sentimento de alguém sobre um fato; pode ser defendida, mas não comprovada como um dado.',
    '- Ex.: “A escola é a melhor da cidade.” “A chuva estragou o fim de semana.” “Esse filme é chato.”',
    '- Um mesmo fato gera opiniões diferentes: “A passagem de ônibus aumentou.” → “É um absurdo!” / “O aumento era necessário.”',
    '# Marcas de opinião na linguagem',
    '- Adjetivos avaliativos: ótimo, péssimo, lamentável, excelente, injusto, incrível, vergonhoso.',
    '- Verbos e expressões de opinião: acho, penso, acredito, considero, na minha opinião, a meu ver.',
    '- Advérbios e expressões de avaliação: felizmente, infelizmente, lamentavelmente, ainda bem que, finalmente (= até que enfim).',
    '- Modalizadores de dúvida: talvez, provavelmente, possivelmente. De certeza: certamente, sem dúvida, evidentemente.',
    '- Expressões de obrigação ou recomendação: deve, precisa, é necessário, é preciso.',
    '- Escolha das palavras: “gastou” x “investiu”; “teimoso” x “persistente”; “velho” x “experiente”.',
    '# Ponto de vista do autor',
    '- É a posição que o autor assume sobre o tema; aparece nas marcas de opinião e nos fatos que ele escolhe mostrar.',
    '- Pergunta-chave: o autor é a favor, contra, preocupado, irônico, otimista?',
    '# Notícia x artigo de opinião',
    '- Notícia: relata fatos de forma objetiva, em 3ª pessoa, e busca a imparcialidade (ainda assim, o título e a seleção dos fatos podem revelar um olhar).',
    '- Artigo de opinião: defende um ponto de vista com argumentos; é assinado pelo autor e pode usar a 1ª pessoa.',
    '# Fique atento',
    '- Relatar a opinião de alguém é um fato: “O diretor disse que a reforma é necessária.” (é fato que ele disse isso).',
    '- Opinião não é mentira: é um ponto de vista, que precisa ser sustentado por argumentos.',
    '- Nas provas, a marca de opinião costuma ser um adjetivo avaliativo, um advérbio como “infelizmente” ou um modalizador.'],
  q=[M('Qual frase expressa um FATO?',
       ['A biblioteca da escola tem dois mil livros.', 'A biblioteca da escola é a mais bonita da região.', 'Ler na biblioteca é muito mais agradável.', 'Os livros da biblioteca são interessantíssimos.'], 0),
     M('Qual frase expressa uma OPINIÃO?',
       ['O show foi simplesmente inesquecível.', 'O show começou às 21h.', 'O show aconteceu na praça central.', 'O show durou duas horas.'], 0),
     A('Classifique em FATO ou OPINIÃO: I. “As aulas voltaram na segunda-feira.” II. “Felizmente, as aulas voltaram.”',
       'I. fato; II. opinião: o advérbio “felizmente” traz a avaliação de quem fala.'),
     T('A prefeitura de uma cidade do interior inaugurou, no último sábado, uma ciclofaixa de 4 quilômetros que liga o centro à rodoviária. A obra levou seis meses, segundo a Secretaria de Obras. Na manhã da inauguração, dezenas de ciclistas percorreram o trajeto. Os comerciantes da avenida principal se dividiram: parte deles reclamou da perda de vagas de estacionamento, e outra parte acredita que o movimento nas lojas vai aumentar.',
       fonte='Notícia elaborada para esta atividade.', titulo='Cidade inaugura ciclofaixa entre o centro e a rodoviária', para=3),
     M('A notícia procura ser imparcial porque:',
       ['relata os fatos e apresenta as duas reações dos comerciantes, sem tomar partido', 'defende a construção de ciclofaixas em todas as cidades', 'critica os comerciantes que reclamaram das vagas', 'usa a primeira pessoa e conta a experiência do autor'], 0),
     M('O trecho “outra parte acredita que o movimento nas lojas vai aumentar”:',
       ['relata a opinião de alguns comerciantes, sem que o jornalista a assuma', 'mostra que o jornalista defende os comerciantes', 'apresenta um dado comprovado por uma pesquisa', 'é um fato porque o movimento das lojas já aumentou'], 0),
     A('Retire da notícia duas informações que podem ser verificadas (fatos).',
       'Duas destas: a ciclofaixa tem 4 quilômetros; liga o centro à rodoviária; foi inaugurada no último sábado; a obra levou seis meses; dezenas de ciclistas percorreram o trajeto.', 2),
     T('Finalmente nossa cidade ganhou uma ciclofaixa. Demorou, mas chegou! Quem pedala para trabalhar sabe o perigo que é dividir a avenida com carros e ônibus. Infelizmente, alguns comerciantes ainda acham que uma vaga de estacionamento vale mais do que a segurança de um trabalhador. A meu ver, a ciclofaixa é só o começo: precisamos de bicicletários, sinalização e campanhas de respeito no trânsito. Uma cidade boa para quem pedala certamente é melhor para todos.',
       fonte='Artigo de opinião elaborado para esta atividade.', titulo='Demorou, mas chegou', para=4),
     M('Qual é o ponto de vista do autor do artigo?',
       ['É a favor da ciclofaixa e defende mais ações para os ciclistas', 'É contra a ciclofaixa porque ela tira vagas de estacionamento', 'Não tem opinião e apenas relata o que aconteceu', 'Acha que a ciclofaixa foi um desperdício de dinheiro'], 0),
     A('Copie do artigo três palavras ou expressões que marcam opinião.',
       'Três destas: “Finalmente”; “Demorou, mas chegou!”; “Infelizmente”; “A meu ver”; “precisamos”; “certamente”; “boa”; “melhor para todos”.', 2),
     M('Em “Uma cidade boa para quem pedala certamente é melhor para todos”, a palavra “certamente” é um modalizador que indica:',
       ['certeza do autor sobre o que afirma', 'dúvida do autor sobre o que afirma', 'o momento em que o fato aconteceu', 'o lugar onde o fato aconteceu'], 0),
     M('Comparando a notícia e o artigo, é correto afirmar que:',
       ['tratam do mesmo fato, mas a notícia informa e o artigo opina', 'os dois defendem abertamente a construção da ciclofaixa', 'a notícia usa a primeira pessoa, e o artigo não', 'o artigo apresenta mais dados verificáveis do que a notícia'], 0),
     M('Em “Infelizmente, o show foi cancelado por causa da chuva”, a marca de opinião é:',
       ['infelizmente', 'show', 'cancelado', 'chuva'], 0),
     M('Qual frase relata a opinião de alguém, mas é, ela mesma, um FATO?',
       ['A professora disse que o livro é excelente.', 'O livro é excelente.', 'Acho que o livro é excelente.', 'Sem dúvida, o livro é excelente.'], 0),
     M('Qual palavra substitui “gastou” em “A prefeitura gastou dinheiro na reforma da praça” e deixa a avaliação POSITIVA?',
       ['investiu', 'desperdiçou', 'torrou', 'esbanjou'], 0),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('Uma opinião pode ser defendida com argumentos.', True),
         ('Todo texto que traz números apresenta apenas fatos.', False),
         ('“Talvez” e “provavelmente” indicam dúvida.', True),
         ('A notícia costuma usar a 1ª pessoa para dar a opinião do jornalista.', False),
         ('A escolha das palavras pode revelar o ponto de vista do autor.', True)]),
     C('Associe cada marca de opinião ao seu tipo:',
       [('lamentável', 'adjetivo avaliativo'), ('infelizmente', 'advérbio de avaliação'), ('talvez', 'modalizador de dúvida'),
        ('sem dúvida', 'modalizador de certeza'), ('a meu ver', 'expressão de opinião')]),
     A('Transforme o fato em opinião, acrescentando uma marca de opinião: “O ônibus atrasou vinte minutos.”',
       'Resposta pessoal. Ex.: Infelizmente, o ônibus atrasou vinte minutos. / O ônibus teve um atraso inaceitável de vinte minutos.'),
     A('Reescreva a frase de forma impessoal, como em uma notícia: “Achei lamentável que a quadra da escola continue fechada.”',
       'A quadra da escola continua fechada.'),
  ],
  producao='Escolha um fato da sua escola ou do seu bairro (uma obra, um evento, uma mudança). Escreva uma notícia curta (3 ou 4 linhas, sem opinião) e, depois, um parágrafo de opinião (5 a 7 linhas) sobre o mesmo fato, com pelo menos três marcas de opinião. Sublinhe essas marcas.')

E(35, B, 'Tipos textuais: narrar, descrever, expor, argumentar e instruir',
  aquecimento='Como você explicaria a um colega o caminho da sua casa até a escola? E como contaria algo engraçado que aconteceu nesse caminho? O que muda no jeito de falar?',
  quadro=['# Tipo textual x gênero textual',
    '- Tipo textual: o modo de organizar o texto (narrar, descrever, expor, argumentar, instruir). São poucos.',
    '- Gênero textual: o texto concreto que circula na sociedade (notícia, receita, conto, bula, anúncio...). São muitos.',
    '# Narrar: contar fatos em sequência',
    '- Elementos: narrador, personagens, tempo, espaço e enredo (situação inicial, conflito, clímax, desfecho).',
    '- Marcas: verbos de ação no pretérito e marcadores de tempo (um dia, depois, de repente). Gêneros: conto, fábula, relato.',
    '# Descrever: mostrar como é',
    '- Retrata seres, objetos, lugares ou sentimentos, como uma “fotografia” em palavras.',
    '- Marcas: muitos adjetivos, verbos como ser, estar, ter e parecer, e comparações. Ex.: “A casa era pequena, de janelas azuis.”',
    '# Expor: explicar e informar',
    '- Apresenta e explica um assunto de forma objetiva, sem defender uma opinião.',
    '- Marcas: presente do indicativo, 3ª pessoa, definições, dados e exemplos. Gêneros: verbete, texto didático, seminário.',
    '# Argumentar: defender um ponto de vista',
    '- Apresenta uma tese (opinião) e argumentos para convencer o leitor.',
    '- Marcas: opinião, modalizadores e conectivos de causa, oposição e conclusão. Gêneros: artigo de opinião, editorial, redação do ENEM.',
    '# Instruir (injuntivo): orientar o leitor',
    '- Ensina a fazer algo ou indica como agir.',
    '- Marcas: verbos no imperativo ou no infinitivo, passos numerados, ordem das etapas. Gêneros: receita, manual, regras de jogo.',
    '# Um gênero, várias sequências',
    '- Os textos costumam misturar tipos: um conto narra, mas descreve personagens; uma receita lista ingredientes e dá o modo de fazer.',
    '- O tipo predominante é o que organiza a maior parte do texto e cumpre a sua finalidade principal.',
    '# Fique atento',
    '- Narrar conta o que aconteceu; expor explica como algo é ou funciona; argumentar quer convencer.',
    '- O texto expositivo informa sem tomar partido; se há uma tese defendida, o texto é argumentativo.',
    '- A redação do ENEM é dissertativo-argumentativa: contar uma história no lugar de argumentar não atende ao tipo e zera a redação.'],
  q=[M('Um texto que ensina a montar um móvel, com passos numerados e verbos como “encaixe” e “aperte”, é do tipo:',
       ['instrucional (injuntivo)', 'narrativo', 'descritivo', 'argumentativo'], 0),
     M('Qual trecho é predominantemente DESCRITIVO?',
       ['A sala era ampla, com paredes amarelas e uma janela que dava para o mar.', 'Ontem saí cedo, peguei o ônibus e cheguei atrasado.', 'Bata as claras em neve e misture tudo devagar.', 'É preciso investir em educação, pois ela transforma vidas.'], 0),
     A('Que tipo textual predomina em “Era uma vez um menino que morava perto de um rio. Um dia, ele encontrou uma garrafa com um bilhete dentro.”?',
       'Narrativo: conta fatos em sequência, com personagem, tempo e espaço.'),
     T('I. “Misture a farinha e o açúcar. Depois, acrescente os ovos, um a um, e mexa até a massa ficar lisa.”\n'
       'II. “O baobá é uma árvore de origem africana. Seu tronco armazena grande quantidade de água, o que ajuda a planta a sobreviver às secas.”\n'
       'III. “Quando a luz acabou, Joana acendeu uma vela. De repente, ouviu passos na escada e prendeu a respiração.”\n'
       'IV. “As escolas deveriam oferecer aulas de educação financeira, porque muitos jovens chegam à vida adulta sem saber controlar os próprios gastos.”\n'
       'V. “A praça tinha bancos de madeira descascados, um coreto antigo e mangueiras enormes que faziam sombra o dia inteiro.”',
       fonte=FONTE, titulo='Cinco trechos', para=4),
     A('Escreva o tipo textual que predomina em cada trecho (I a V).',
       'I. instrucional (injuntivo); II. expositivo; III. narrativo; IV. argumentativo; V. descritivo.', 2,
       banco=['narrativo', 'descritivo', 'expositivo', 'argumentativo', 'instrucional']),
     M('No trecho I, a marca linguística que mais caracteriza o tipo textual é:',
       ['o uso de verbos no imperativo (misture, acrescente, mexa)', 'o uso de adjetivos que descrevem a massa', 'a presença de personagens e de um conflito', 'a defesa de uma opinião com argumentos'], 0),
     M('O trecho IV é argumentativo porque:',
       ['defende uma opinião (tese) e apresenta uma justificativa', 'conta um fato que aconteceu com uma personagem', 'ensina o leitor a fazer algo, passo a passo', 'descreve as características de um lugar'], 0),
     M('Qual diferença entre os trechos II e IV está correta?',
       ['II explica um assunto sem tomar partido; IV defende um ponto de vista', 'II defende uma opinião; IV apenas informa dados', 'II e IV contam fatos em sequência temporal', 'II e IV dão ordens ao leitor com verbos no imperativo'], 0),
     T('Na fila do posto de saúde, uma senhora de cabelos brancos e vestido florido segurava uma sacola de pano. Quando chegou a vez dela, a atendente explicou que o sistema estava fora do ar. A senhora não reclamou: abriu a sacola, tirou uma garrafa de café e ofereceu a todos da fila. Em poucos minutos, desconhecidos conversavam como velhos amigos. Às vezes, acho que a paciência é uma forma de gentileza que estamos esquecendo.',
       fonte=FONTE, titulo='O café da fila', para=3),
     M('O tipo textual que predomina no texto é o:',
       ['narrativo', 'instrucional', 'expositivo', 'argumentativo'], 0),
     A('Copie do texto um trecho descritivo.', '“uma senhora de cabelos brancos e vestido florido” (ou “uma sacola de pano”).'),
     M('A última frase (“Às vezes, acho que a paciência é uma forma de gentileza que estamos esquecendo”) acrescenta ao texto:',
       ['uma reflexão com a opinião do narrador', 'uma instrução para o leitor seguir', 'uma descrição do posto de saúde', 'um novo conflito para a história'], 0),
     M('Uma bula de remédio tem partes como “Composição”, “Para que este medicamento é indicado?” e “Como devo usar este medicamento?”. Isso mostra que:',
       ['um mesmo gênero pode reunir sequências expositivas e instrucionais', 'a bula é um gênero exclusivamente narrativo', 'a bula é argumentativa, pois defende o remédio', 'tipo textual e gênero textual são a mesma coisa'], 0),
     M('Qual alternativa relaciona corretamente o gênero ao tipo textual predominante?',
       ['receita – instrucional', 'conto – argumentativo', 'verbete de dicionário – narrativo', 'artigo de opinião – descritivo'], 0),
     M('Em qual situação o tipo EXPOSITIVO é o mais adequado?',
       ['explicar, em um seminário, como as vacinas protegem o corpo', 'contar aos amigos como foi a viagem de férias', 'convencer o diretor a liberar a quadra no recreio', 'ensinar o passo a passo de uma receita de bolo'], 0),
     C('Associe o tipo textual à sua finalidade principal:',
       [('narrar', 'contar fatos vividos por personagens no tempo'), ('descrever', 'mostrar como é um ser, objeto ou lugar'),
        ('expor', 'explicar um assunto de forma objetiva'), ('argumentar', 'convencer o leitor de um ponto de vista'),
        ('instruir', 'orientar o leitor a fazer algo')]),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('Gênero textual e tipo textual são a mesma coisa.', False),
         ('Um conto pode ter trechos descritivos.', True),
         ('Verbos no imperativo são comuns em textos instrucionais.', True),
         ('O texto expositivo sempre defende uma opinião.', False),
         ('A redação do ENEM deve ser do tipo dissertativo-argumentativo.', True)]),
     A('Transforme a instrução em narração: “Abra a porta, entre devagar e acenda a luz.”',
       'Ex.: Ele abriu a porta, entrou devagar e acendeu a luz.'),
     A('Escreva uma frase descritiva sobre a sua sala de aula, com pelo menos dois adjetivos.',
       'Resposta pessoal. Ex.: A sala é clara e espaçosa, com carteiras azuis e um quadro enorme.'),
  ],
  producao='Escolha um lugar da sua cidade e escreva um texto de 8 a 10 linhas em três partes: descreva o lugar (2 ou 3 linhas), narre algo que aconteceu ali (3 ou 4 linhas) e termine com a sua opinião sobre a importância desse lugar (2 ou 3 linhas).')

E(36, B, 'Gêneros textuais: notícia, reportagem, artigo de opinião, crônica e editorial',
  aquecimento='Onde vocês costumam se informar: TV, site, rede social, jornal impresso? Qual é a diferença entre uma notícia curta e uma matéria longa que investiga um assunto?',
  quadro=['# Gêneros jornalísticos: para que servem',
    '- Notícia: informa um fato recente, de interesse público, de forma objetiva e impessoal.',
    '- Reportagem: aprofunda um assunto com pesquisa, entrevistas, dados e vários pontos de vista; é mais longa.',
    '- Artigo de opinião: um autor, que assina o texto, defende o seu ponto de vista com argumentos; pode usar a 1ª pessoa.',
    '- Editorial: expressa a opinião do próprio jornal, revista ou site sobre um tema atual; não é assinado.',
    '- Crônica: texto curto que parte de um fato do cotidiano para provocar reflexão, humor ou emoção; linguagem próxima da conversa.',
    '# Estrutura da notícia',
    '- Manchete (título): curta, chamativa, em geral com verbo no presente. Ex.: “Chuva alaga ruas do centro”.',
    '- Linha fina (subtítulo): complementa a manchete com mais uma informação.',
    '- Lead (lide): o primeiro parágrafo, que responde às perguntas o quê? quem? quando? onde? como? por quê?',
    '- Corpo: detalhes em ordem decrescente de importância (pirâmide invertida), com falas de testemunhas ou especialistas.',
    '# Notícia x reportagem',
    '- Notícia: fato do dia, texto curto, informação imediata. Reportagem: tema investigado, texto longo, contexto e análise.',
    '- Ex.: notícia: “Ponte é interditada após rachaduras”; reportagem: “Por que as pontes da cidade estão em risco?”, com dados, entrevistas e histórico.',
    '# Artigo de opinião x editorial',
    '- Os dois argumentam. O artigo traz a opinião de um autor, que o assina; o editorial traz a opinião do veículo.',
    '# A crônica',
    '- Nasce no jornal, mas tem um pé na literatura: transforma cenas do dia a dia em reflexão, com humor ou lirismo.',
    '- Ex.: uma fila de banco, uma conversa no ônibus ou uma chuva de verão viram assunto para pensar a vida.',
    '- Cronistas brasileiros: Machado de Assis, Lima Barreto, Rubem Braga, Rachel de Queiroz, Fernando Sabino, Luis Fernando Verissimo.',
    '# Fique atento',
    '- A notícia não deve trazer a opinião do jornalista; se há uma tese defendida com argumentos, o texto é opinativo.',
    '- O editorial não é assinado; o artigo de opinião é.',
    '- Crônica não é notícia: o fato do cotidiano é só o ponto de partida para o olhar pessoal do cronista.'],
  q=[M('Qual gênero informa um fato recente de forma objetiva e impessoal?',
       ['notícia', 'crônica', 'artigo de opinião', 'editorial'], 0),
     M('O texto que expressa a opinião do próprio jornal, sem assinatura, é o:',
       ['editorial', 'artigo de opinião', 'reportagem', 'crônica'], 0),
     A('Quais são as seis perguntas que o lead de uma notícia deve responder?', 'O quê? Quem? Quando? Onde? Como? Por quê?'),
     T('Um forte temporal atingiu a região norte da cidade na tarde desta terça-feira e derrubou ao menos doze árvores, segundo a Defesa Civil. Por causa da queda de galhos sobre a rede elétrica, cerca de três mil imóveis ficaram sem energia. Não houve feridos.\n'
       'A companhia de energia informou que as equipes trabalharam durante a noite e que o fornecimento deve ser totalmente restabelecido até o fim da manhã de quarta-feira. A Defesa Civil recomenda que os moradores não se aproximem de fios caídos e liguem 199 em caso de emergência.',
       fonte='Notícia elaborada para esta atividade.', titulo='Temporal derruba árvores e deixa bairros sem energia', para=4),
     M('O primeiro parágrafo da notícia, que responde às principais perguntas sobre o fato, é chamado de:',
       ['lead (lide)', 'manchete', 'linha fina', 'editorial'], 0),
     A('Responda com informações do primeiro parágrafo: O quê? Onde? Quando? Por que os imóveis ficaram sem energia?',
       'O quê: um temporal derrubou árvores e deixou imóveis sem energia. Onde: na região norte da cidade. Quando: na tarde desta terça-feira. Por quê: galhos caíram sobre a rede elétrica.', 3),
     M('A manchete “Temporal derruba árvores e deixa bairros sem energia” usa verbos no presente para:',
       ['dar ao fato um efeito de atualidade, de algo que acabou de acontecer', 'indicar que o temporal ainda vai acontecer', 'mostrar a opinião do jornalista sobre o fato', 'deixar claro que o fato foi inventado pelo autor'], 0),
     M('A notícia cita a Defesa Civil e a companhia de energia para:',
       ['dar credibilidade às informações, indicando as fontes', 'mostrar que o jornalista discorda das autoridades', 'criar humor e aproximar o texto de uma crônica', 'defender uma opinião sobre o serviço de energia'], 0),
     T('Todo dia, no ônibus das sete, o mesmo senhor sobe com um radinho de pilha colado ao ouvido. Ninguém sabe o nome dele, mas todos sabem o placar do jogo da noite anterior, porque ele anuncia o resultado em voz alta, como um locutor. Hoje, o radinho falhou. O senhor sacudiu o aparelho, bateu de leve, e nada. O ônibus inteiro ficou em silêncio, meio sem graça. Foi então que a cobradora, sem tirar os olhos do troco, gritou: “Deu dois a um, gente!”. E a viagem seguiu, de novo, com a cidade inteira dentro do ônibus.',
       fonte='Crônica elaborada para esta atividade.', titulo='O ônibus das sete', para=3),
     M('Esse texto é uma crônica porque:',
       ['parte de uma cena comum do cotidiano e a transforma em uma reflexão leve e afetiva', 'informa um fato de interesse público, com lead e fontes oficiais', 'defende uma tese com argumentos e dados de pesquisa', 'expressa a opinião oficial de um jornal sobre um tema atual'], 0),
     M('A frase final, “com a cidade inteira dentro do ônibus”, sugere que:',
       ['o ônibus voltou a ser um lugar de convivência e alegria compartilhada', 'o ônibus estava lotado com toda a população da cidade', 'todos os moradores da cidade escutaram o rádio do senhor', 'o motorista mudou o trajeto para passar pelo centro'], 0),
     A('Cite duas diferenças entre a crônica “O ônibus das sete” e a notícia do temporal.',
       'Ex.: a crônica tem linguagem pessoal e literária, e a notícia é objetiva; a crônica narra uma cena do cotidiano para emocionar e fazer refletir, e a notícia informa um fato de interesse público; a notícia tem lead e fontes, e a crônica não.', 3),
     M('Na pirâmide invertida, usada na notícia, as informações aparecem:',
       ['das mais importantes para as menos importantes', 'das menos importantes para as mais importantes', 'em ordem alfabética dos nomes citados', 'na ordem em que o jornalista as descobriu'], 0),
     M('Qual título é mais provável para uma REPORTAGEM, e não para uma notícia?',
       ['Por que tantos jovens deixam o ensino médio? Especialistas e estudantes explicam', 'Ônibus quebra na avenida principal e causa congestionamento', 'Prefeitura anuncia vacinação contra a gripe nesta segunda', 'Time local vence a final do campeonato por 2 a 1'], 0),
     M('Um texto assinado por uma médica e publicado em um jornal defende, com argumentos, que as escolas tenham aulas sobre saúde mental. Esse texto é um:',
       ['artigo de opinião', 'editorial', 'lead', 'verbete'], 0),
     C('Associe o gênero à sua característica:',
       [('notícia', 'relata um fato recente de forma objetiva'), ('reportagem', 'aprofunda um tema com entrevistas e dados'),
        ('artigo de opinião', 'defende o ponto de vista de um autor que o assina'), ('editorial', 'apresenta a opinião do jornal, sem assinatura'),
        ('crônica', 'reflete sobre o cotidiano com linguagem leve')]),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('A reportagem costuma ser mais longa e aprofundada do que a notícia.', True),
         ('O editorial é assinado por um leitor do jornal.', False),
         ('A crônica costuma partir de fatos simples do cotidiano.', True),
         ('A notícia deve trazer a opinião do jornalista no lead.', False),
         ('O artigo de opinião e o editorial são gêneros argumentativos.', True)]),
     A('Escreva uma manchete para este fato: “No sábado, alunos de uma escola municipal plantaram cem mudas de árvores na praça do bairro.”',
       'Resposta pessoal. Ex.: Alunos plantam cem mudas de árvores na praça do bairro.'),
  ],
  producao='Escolha um acontecimento simples do seu dia a dia (na escola, no ônibus, em casa) e escreva sobre ele de duas formas: primeiro, uma notícia curta, com manchete e lead (3 a 5 linhas); depois, uma crônica de 6 a 8 linhas, com olhar pessoal, humor ou reflexão.')

E(37, B, 'Linguagem verbal e não verbal: charge, tirinha, cartum e propaganda',
  aquecimento='Que placas, símbolos ou emojis vocês entendem sem ler nenhuma palavra? (Ex.: semáforo, “proibido fumar”, joinha.) Como um desenho consegue “falar”?',
  quadro=['# Linguagem verbal, não verbal e mista',
    '- Verbal: usa palavras, faladas ou escritas. Não verbal: usa imagens, cores, gestos, sons e símbolos.',
    '- Mista (multimodal): junta palavras e imagens. Ex.: placas, anúncios, memes, tirinhas, infográficos.',
    '- Na leitura, imagem e palavra se completam: um detalhe do desenho pode mudar todo o sentido da frase.',
    '# Charge',
    '- Desenho de humor que critica um fato ATUAL (política, economia, comportamento); costuma usar caricaturas.',
    '- Para entendê-la, é preciso conhecer a notícia do momento; por isso, a charge “envelhece” rápido.',
    '# Cartum',
    '- Também é humorístico e crítico, mas trata de temas universais e atemporais (vida moderna, relações humanas, tecnologia).',
    '- É entendido em qualquer época, sem depender de uma notícia específica.',
    '# Tirinha (tira)',
    '- Sequência curta de quadrinhos (em geral de 2 a 4), com personagens, balões e humor.',
    '- O humor costuma vir de um desfecho inesperado no último quadrinho (quebra de expectativa).',
    '- Recursos: balão de fala, de pensamento (nuvem) e de grito (pontudo); onomatopeias (POW!, TRIIIM!); expressões do rosto.',
    '# Propaganda e publicidade',
    '- Objetivo: persuadir o leitor a comprar um produto (publicidade) ou a aderir a uma ideia ou campanha (propaganda).',
    '- Recursos: imagem chamativa, slogan curto e fácil de lembrar, verbos no imperativo (Experimente! Vacine-se!), apelo emocional, humor.',
    '- Fala diretamente com o leitor (“você”) e procura despertar um desejo ou uma necessidade.',
    '# Ironia e humor',
    '- Ironia: dizer o contrário do que se pensa, para criticar ou fazer rir; o contexto ou a imagem revelam a ironia.',
    '- Ex.: um desenho mostra um rio cheio de lixo com a placa “Bem-vindo ao paraíso”.',
    '# Fique atento',
    '- Leia TUDO: título, balões, legendas, expressões, cores e detalhes do cenário.',
    '- Charge = fato atual; cartum = tema atemporal; tirinha = sequência de quadrinhos.',
    '- Diante de uma propaganda, pergunte: quem quer convencer, quem, de quê e com quais recursos?'],
  q=[M('Uma placa apenas com o desenho de um cigarro cortado por uma faixa vermelha usa linguagem:',
       ['não verbal', 'verbal', 'mista', 'formal'], 0),
     M('Um anúncio com a foto de um tênis e a frase “Corra mais longe” usa linguagem:',
       ['mista (verbal e não verbal)', 'apenas verbal', 'apenas não verbal', 'apenas sonora'], 0),
     A('Explique a diferença entre charge e cartum.',
       'A charge critica um fato atual e específico (por isso envelhece rápido); o cartum faz humor crítico sobre temas universais, que valem para qualquer época.', 2),
     T('Tirinha em três quadrinhos.\n'
       '1º quadrinho: um menino entra em casa com o boletim na mão e diz: “Mãe, tenho uma notícia boa e uma ruim.” A mãe, sorrindo, responde: “Comece pela boa!”\n'
       '2º quadrinho: o menino diz: “Tirei a nota mais alta da turma em Matemática!” A mãe abre os braços, emocionada.\n'
       '3º quadrinho: o menino completa: “A ruim é que a nota mais alta foi 4.” A mãe aparece paralisada, com os olhos arregalados e uma gota de suor na testa.',
       fonte='Tirinha descrita em palavras, elaborada para esta atividade.', titulo='A notícia boa', para=4),
     M('O humor da tirinha está principalmente:',
       ['na quebra de expectativa do último quadrinho, que transforma a notícia boa em ruim', 'no fato de o menino ter tirado a nota mais alta da turma', 'na alegria da mãe ao receber o boletim do filho', 'na descrição detalhada da casa onde a família mora'], 0),
     M('No último quadrinho, a expressão da mãe (olhos arregalados e gota de suor) é linguagem não verbal que indica:',
       ['espanto e preocupação', 'orgulho e alegria', 'sono e cansaço', 'indiferença e tédio'], 0),
     M('Pela tirinha, é possível inferir que:',
       ['as notas da turma toda em Matemática foram baixas', 'o menino foi o único aprovado da escola', 'a mãe já sabia qual era a nota do filho', 'a professora de Matemática errou a correção'], 0),
     A('Explique por que a “notícia boa” e a “notícia ruim” se referem, na verdade, ao mesmo fato.',
       'Porque a nota mais alta da turma (notícia boa) é a nota 4 (notícia ruim): o mesmo fato é visto de dois jeitos — foi a melhor nota da turma, mas é uma nota baixa.', 2),
     T('Charge publicada durante uma onda de calor que atingiu o país. O desenho mostra um homem derretendo como um sorvete em um ponto de ônibus, ao lado de um termômetro que marca 45 °C. Na parede do ponto, há um cartaz da prefeitura: “Aproveite o verão! Beba água e evite o sol.” O ponto não tem cobertura nem bebedouro.',
       fonte='Charge descrita em palavras, elaborada para esta atividade.', titulo='Verão na cidade', para=4),
     M('O texto descrito é uma charge, e não um cartum, porque:',
       ['critica um fato atual: uma onda de calor que atingiu o país', 'conta uma história em vários quadrinhos com personagens fixos', 'trata de um tema universal, que vale para qualquer época', 'tem o objetivo de vender um produto ao leitor'], 0),
     M('A crítica da charge está na contradição entre:',
       ['o cartaz que recomenda evitar o sol e o ponto de ônibus sem cobertura nem bebedouro', 'o calor intenso e as roupas leves que o homem está usando', 'o termômetro que marca 45 °C e a temperatura real da cidade', 'a espera pelo ônibus e o horário de funcionamento do transporte'], 0),
     M('O homem “derretendo como um sorvete” é um recurso visual de:',
       ['exagero, para mostrar o calor extremo', 'descrição objetiva, como em uma notícia', 'instrução, como em um manual', 'linguagem exclusivamente verbal'], 0),
     A('O cartaz diz “Aproveite o verão!”. Explique a ironia dessa frase no contexto da charge.',
       'O cartaz convida a “aproveitar” o verão, mas o homem está sofrendo com o calor, sem cobertura nem água: a frase contrasta com a situação real e critica a falta de estrutura oferecida à população.', 2),
     M('Em uma tirinha, um balão com contorno de nuvem, ligado ao personagem por bolinhas, indica:',
       ['pensamento', 'grito', 'cochicho', 'fala do narrador'], 0),
     M('Descrição de um anúncio: um copo de suco de laranja com gotas geladas e, abaixo, o slogan “Suco Sol: o sabor que acorda você!”. O principal objetivo desse texto é:',
       ['convencer o leitor a comprar o suco', 'ensinar a preparar um suco de laranja', 'noticiar a produção de laranjas no país', 'criticar o consumo de bebidas industrializadas'], 0),
     M('Em uma campanha de vacinação, a frase “Vacine-se! Proteja quem você ama.” usa:',
       ['verbos no imperativo e apelo emocional', 'apenas linguagem não verbal', 'narração de fatos passados', 'ironia para criticar a vacina'], 0),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('A tirinha costuma ter um desfecho inesperado no último quadrinho.', True),
         ('O cartum depende de uma notícia do dia para ser entendido.', False),
         ('Slogan é uma frase curta e fácil de lembrar, usada em anúncios e campanhas.', True),
         ('Na linguagem mista, a imagem não interfere no sentido do texto.', False),
         ('A ironia diz o contrário do que se quer realmente dizer.', True)]),
     C('Associe cada termo à sua definição:',
       [('charge', 'critica um fato atual'), ('cartum', 'faz humor sobre um tema atemporal'), ('tirinha', 'sequência curta de quadrinhos'),
        ('slogan', 'frase curta e marcante de um anúncio'), ('onomatopeia', 'palavra que imita um som')]),
     A('Crie um slogan para uma campanha da escola contra o desperdício de comida no refeitório.',
       'Resposta pessoal. Ex.: “Prato limpo, planeta feliz!”'),
  ],
  producao='Crie, em palavras, uma tirinha de três quadrinhos sobre a vida escolar: descreva o que aparece em cada quadrinho (cenário, personagens, expressões) e escreva as falas dos balões. O último quadrinho deve ter um desfecho inesperado. Se quiser, desenhe também.')

E(38, B, 'Intertextualidade: citação, paráfrase, paródia e alusão',
  aquecimento='Quem já viu um meme, uma propaganda ou uma música que “brinca” com um conto de fadas, um filme ou um ditado conhecido? Para achar graça, o que a gente precisa conhecer antes?',
  quadro=['# O que é intertextualidade',
    '- É o diálogo entre textos: um texto retoma, cita ou faz referência a outro, já conhecido.',
    '- Para perceber o diálogo, o leitor precisa conhecer o texto de origem: é o seu repertório de leitura.',
    '# Citação',
    '- Reprodução fiel das palavras de outro texto, entre aspas e com a indicação do autor.',
    '- Ex.: o Hino Nacional cita a “Canção do Exílio” (1843), de Gonçalves Dias: “Nossos bosques têm mais vida”, “Nossa vida” no teu seio “mais amores”.',
    '- Epígrafe: citação colocada no início de um livro, capítulo ou poema para anunciar o tema. A “Canção do Exílio” abre com uma epígrafe do alemão Goethe.',
    '# Paráfrase',
    '- Diz a mesma ideia do texto original com outras palavras, sem mudar o sentido.',
    '- Ex.: “Na minha terra há palmeiras onde canta o sabiá; os pássaros daqui não cantam como os de lá.”',
    '# Paródia',
    '- Retoma a forma de um texto conhecido, mas muda o seu sentido, com humor, ironia ou crítica.',
    '- Ex.: “Minha terra tem palmeiras / Onde canta o celular...” (brinca com a vida conectada).',
    '- Em 1925, Oswald de Andrade trocou “palmeiras” por “palmares” no “Canto de regresso à pátria”, lembrando o Quilombo dos Palmares.',
    '# Alusão (referência)',
    '- Menção indireta a um texto, personagem ou fato conhecido, sem citá-lo por inteiro.',
    '- Ex.: “Aquela prova foi o meu calcanhar de Aquiles.” (mitologia grega) / “Ele é um verdadeiro Romeu.” (Shakespeare)',
    '# Paráfrase x paródia',
    '- Paráfrase: mesma ideia, outras palavras (acompanha o original). Paródia: forma parecida, ideia diferente (subverte o original).',
    '- Pastiche: imitação do estilo de um autor ou de uma época, sem intenção de crítica.',
    '# Fique atento',
    '- Citação precisa de aspas e de fonte; copiar o texto de outra pessoa sem isso é plágio.',
    '- A intertextualidade é comum em propagandas, memes, charges, músicas e títulos de notícias.',
    '- Na redação, citar um autor ou uma obra só ajuda se a citação tiver relação com o tema e for explicada.'],
  q=[M('Quando um texto retoma, cita ou faz referência a outro texto, ocorre:',
       ['intertextualidade', 'ambiguidade', 'redundância', 'variação linguística'], 0),
     M('Reproduzir as palavras exatas de um autor, entre aspas e com a fonte, é fazer uma:',
       ['citação', 'paródia', 'alusão', 'paráfrase'], 0),
     A('Qual é a diferença entre paráfrase e paródia?',
       'A paráfrase diz a mesma ideia com outras palavras, sem mudar o sentido; a paródia imita a forma do texto, mas muda o sentido, com humor ou crítica.', 2),
     T('Minha terra tem palmeiras, / Onde canta o Sabiá; / As aves, que aqui gorjeiam, / Não gorjeiam como lá. // Nosso céu tem mais estrelas, / Nossas várzeas têm mais flores, / Nossos bosques têm mais vida, / Nossa vida mais amores. // Em cismar, sozinho, à noite, / Mais prazer encontro eu lá; / Minha terra tem palmeiras, / Onde canta o Sabiá.',
       fonte='Gonçalves Dias, “Canção do Exílio”, 1843 (fragmento). A barra (/) separa os versos, e a barra dupla (//), as estrofes.', titulo='Canção do Exílio', para=3),
     M('No poema, as palavras “aqui” e “lá” se referem, respectivamente:',
       ['ao lugar onde o poeta está, longe da pátria, e à sua terra natal', 'à terra natal do poeta e ao lugar onde ele está agora', 'ao céu estrelado e às várzeas floridas da terra natal', 'à noite em que o poeta escreve e ao dia seguinte'], 0),
     M('O sentimento predominante no poema é:',
       ['a saudade da terra natal', 'a raiva contra a própria pátria', 'a alegria de viver no exterior', 'o medo da natureza selvagem'], 0),
     A('Faça uma paráfrase dos quatro primeiros versos (diga a mesma coisa com outras palavras).',
       'Ex.: Na minha terra há palmeiras onde o sabiá canta; os pássaros que cantam aqui não cantam como os de lá.', 2),
     T('Texto I: Minha terra tem palmares / Onde gorjeia o mar / Os passarinhos daqui / Não cantam como os de lá\n'
       'Texto II: Minha terra tem palmeiras / Onde canta o celular; / As aves que aqui gorjeiam / Não têm sinal como lá.',
       fonte='Texto I: Oswald de Andrade, “Canto de regresso à pátria”, 1925 (fragmento). Texto II: elaborado para esta atividade.', titulo='Dois diálogos com a “Canção do Exílio”', para=4),
     M('Os textos I e II retomam a forma da “Canção do Exílio”, mas mudam o seu sentido. Esse tipo de intertextualidade é a:',
       ['paródia', 'paráfrase', 'citação', 'epígrafe'], 0),
     M('No texto II, o humor nasce principalmente:',
       ['da troca do canto do sabiá pelo toque do celular, que brinca com a vida conectada', 'da descrição fiel das palmeiras e dos pássaros brasileiros', 'da repetição exata dos versos de Gonçalves Dias', 'da tristeza do poeta por estar longe da família'], 0),
     M('No texto I, a troca de “palmeiras” por “palmares” pode ser lida como:',
       ['uma alusão ao Quilombo dos Palmares, símbolo da resistência negra', 'um erro de impressão, corrigido nas edições seguintes', 'uma paráfrase que mantém o sentido do texto original', 'uma citação fiel do primeiro verso da “Canção do Exílio”'], 0),
     A('Copie do texto I um verso que dialoga com a “Canção do Exílio” e indique a qual verso original ele corresponde.',
       'Ex.: “Minha terra tem palmares” corresponde a “Minha terra tem palmeiras”; ou “Não cantam como os de lá” corresponde a “Não gorjeiam como lá”.', 2),
     M('Em “Aquela prova de Física foi o meu calcanhar de Aquiles”, há uma alusão à mitologia grega. A expressão significa:',
       ['o ponto fraco de alguém', 'uma grande vitória', 'uma corrida muito longa', 'um presente enganoso'], 0),
     M('O Hino Nacional traz os versos “Nossos bosques têm mais vida”, “Nossa vida” no teu seio “mais amores”, com aspas. As aspas indicam:',
       ['uma citação da “Canção do Exílio”, de Gonçalves Dias', 'uma paródia que critica o poema de Gonçalves Dias', 'a fala de um personagem, como em um diálogo', 'uma ironia, pois o autor discorda do que escreveu'], 0),
     M('Um anúncio de academia diz: “Malhar ou não malhar, eis a questão.” Esse slogan dialoga com:',
       ['uma frase famosa da peça “Hamlet”, de Shakespeare', 'um verso da “Canção do Exílio”, de Gonçalves Dias', 'o primeiro verso do Hino Nacional Brasileiro', 'um provérbio popular sobre a saúde'], 0),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('Para perceber uma intertextualidade, o leitor precisa conhecer o texto de origem.', True),
         ('A paráfrase muda totalmente o sentido do texto original.', False),
         ('A epígrafe é uma citação colocada no início de um livro, capítulo ou poema.', True),
         ('Copiar o texto de outra pessoa sem aspas e sem fonte é plágio.', True),
         ('A paródia é sempre uma homenagem séria, sem humor nem crítica.', False)]),
     C('Associe cada tipo de intertextualidade ao exemplo:',
       [('citação', 'Como escreveu Gonçalves Dias: “Minha terra tem palmeiras”.'), ('paráfrase', 'O poeta diz que o céu da sua terra tem mais estrelas.'),
        ('paródia', 'Minha escola tem merenda / Onde canta o cozinheiro.'), ('alusão', 'Longe de casa, ele sentia falta do seu sabiá.')]),
     A('Crie uma paródia de dois versos para “Minha terra tem palmeiras, / Onde canta o Sabiá”, falando da sua escola ou do seu bairro.',
       'Resposta pessoal. Ex.: “Minha escola tem quadra / Onde grita o torcedor.”', 2),
  ],
  producao='Escolha um texto bem conhecido (um provérbio, uma cantiga de roda, um conto de fadas ou a própria “Canção do Exílio”) e escreva uma paródia de 6 a 10 linhas sobre uma situação atual do seu bairro ou da sua cidade. Depois, explique em uma linha qual texto você retomou e o que mudou no sentido.')

E(39, B, 'Variação linguística e adequação: formal e informal',
  aquecimento='Como vocês chamam o pão francês, a mandioca e o semáforo aqui na nossa região? Alguém conhece outro nome usado em outro lugar do Brasil?',
  quadro=['# Toda língua varia',
    '- O português não é falado do mesmo jeito por todos: muda conforme o lugar, o grupo social, a época e a situação.',
    '- Variação não é erro: cada variedade tem as suas regras e serve à comunicação do seu grupo.',
    '# Tipos de variação',
    '- Regional (geográfica): sotaques e palavras de cada lugar. Ex.: mandioca, aipim, macaxeira; “tu vais” ou “você vai”.',
    '- Social: ligada à idade, à escolaridade, à profissão e aos grupos. Ex.: gírias de jovens; jargões de médicos e advogados.',
    '- Histórica: a língua muda com o tempo. Ex.: “Vossa Mercê” → “vosmecê” → “você” → “cê”; “pharmacia” → “farmácia”.',
    '- Situacional (estilística): cada pessoa muda o jeito de falar conforme a situação, do mais formal ao mais informal.',
    '# Registro formal x informal',
    '- Formal: situações sérias ou públicas (entrevista de emprego, documento, redação do ENEM); segue a norma-padrão, sem gírias.',
    '- Informal: situações descontraídas (conversa com amigos, mensagem para a família); aceita gírias, abreviações e frases curtas.',
    '# Gíria e jargão',
    '- Gíria: vocabulário típico de um grupo, muitas vezes passageiro. Ex.: “top”, “de boa”, “mó legal”.',
    '- Jargão: vocabulário técnico de uma profissão. Ex.: “habeas corpus” (Direito), “anamnese” (Medicina).',
    '# Norma-padrão',
    '- É o modelo de língua descrito nas gramáticas e usado em textos oficiais, científicos e escolares.',
    '- Dominá-la amplia oportunidades: ela é exigida em concursos, documentos e na redação do ENEM (competência 1).',
    '# Preconceito linguístico',
    '- É julgar ou ridicularizar alguém pelo seu jeito de falar: sotaque, região, escolaridade. Ex.: rir do sotaque de alguém.',
    '- Em vez de “certo” e “errado”, pense em ADEQUAÇÃO: cada situação pede um registro.',
    '# Adequação ao contexto',
    '- Mensagem a um amigo: “E aí, bora no cinema amanhã?” / Entrevista de emprego: “Tenho disponibilidade para trabalhar aos sábados.”',
    '- Redação do ENEM: norma-padrão, sem gírias, sem abreviações (vc, tb) e sem marcas de oralidade (“tipo assim”, “né”).',
    '# Fique atento',
    '- Linguagem formal demais entre amigos também é inadequada: soa artificial.',
    '- O objetivo é ampliar o repertório, e não apagar o jeito de falar de cada um: quem domina vários registros escolhe o mais adequado.',
    '- Respeitar a variação não dispensa aprender a norma-padrão: as duas coisas caminham juntas.'],
  q=[M('“Mandioca”, “aipim” e “macaxeira” são nomes da mesma raiz usados em lugares diferentes do Brasil. Isso é um exemplo de variação:',
       ['regional', 'histórica', 'social', 'situacional'], 0),
     M('Em qual situação o registro formal é o mais adequado?',
       ['uma entrevista de emprego', 'uma conversa com os amigos no recreio', 'uma mensagem para a irmã', 'uma brincadeira no grupo da família'], 0),
     A('Explique, com suas palavras, o que é preconceito linguístico.',
       'É julgar, ridicularizar ou discriminar uma pessoa pelo seu jeito de falar (sotaque, região, escolaridade, gírias).', 2),
     T('Rafael escreveu duas mensagens no mesmo dia.\n'
       'Mensagem 1 (para um amigo): E aí, Lucas! Blz? Amanhã não vou conseguir ir no futebol, mano. Vou fazer uma entrevista de emprego às 10h. Se der certo, a gente comemora! Abraço!\n'
       'Mensagem 2 (para uma empresa): Prezada Sra. Helena, bom dia. Confirmo minha presença na entrevista de amanhã, às 10h. Agradeço a oportunidade e coloco-me à disposição para quaisquer esclarecimentos. Atenciosamente, Rafael Souza.',
       fonte=FONTE, titulo='Duas mensagens', para=4),
     M('A diferença de linguagem entre as duas mensagens se explica principalmente:',
       ['pela situação de comunicação e pela relação com o destinatário', 'pelo fato de terem sido escritas em dias diferentes', 'pela região do Brasil onde cada destinatário mora', 'pela idade de quem escreveu cada mensagem'], 0),
     A('Copie da mensagem 1 duas marcas de linguagem informal.',
       'Duas destas: “E aí”; “Blz?” (abreviação); “mano” (gíria); “ir no futebol”; “a gente”.', 2),
     M('Se Rafael enviasse a mensagem 1 para a empresa, ela seria:',
       ['inadequada, pois a situação profissional pede o registro formal', 'adequada, pois qualquer mensagem pode ser informal', 'adequada, pois as empresas preferem gírias e abreviações', 'impossível, pois a linguagem informal não faz parte do português'], 0),
     M('A palavra “mano”, na mensagem 1, é um exemplo de:',
       ['gíria', 'jargão profissional', 'variação histórica', 'norma-padrão'], 0),
     T('Quando Josefa chegou de Caruaru para trabalhar em São Paulo, alguns colegas riam do seu sotaque e a imitavam na hora do almoço. Um dia, ela respondeu: “Oxente, vocês nunca viram uma pernambucana falar, não?”, e todos riram de novo. Mas, na reunião da semana seguinte, foi Josefa quem apresentou a melhor proposta do setor, com clareza e segurança. Depois disso, ninguém mais imitou o seu jeito de falar: muitos passaram a perguntar o que significavam as palavras dela.',
       fonte=FONTE, titulo='O sotaque de Josefa', para=3),
     M('A atitude dos colegas no início do texto é um exemplo de:',
       ['preconceito linguístico', 'adequação linguística', 'variação histórica', 'linguagem não verbal'], 0),
     M('A palavra “Oxente”, usada por Josefa, é um exemplo de variação:',
       ['regional', 'histórica', 'social, como um jargão técnico', 'situacional, típica do registro formal'], 0),
     A('Que ideia o final do texto transmite sobre o sotaque de uma pessoa e a sua competência?',
       'Que o sotaque não diz nada sobre a competência de alguém: Josefa falava de um jeito diferente e apresentou a melhor proposta; julgar alguém pelo jeito de falar é preconceito.', 2),
     M('A sequência “Vossa Mercê → vosmecê → você → cê” mostra a variação:',
       ['histórica', 'regional', 'situacional', 'social'], 0),
     M('Na fala de um médico, “O paciente apresentou quadro de cefaleia”, a palavra “cefaleia” (dor de cabeça) é um exemplo de:',
       ['jargão profissional', 'gíria de jovens', 'regionalismo', 'erro de concordância'], 0),
     M('Qual frase está adequada à redação do ENEM?',
       ['Portanto, é necessário que o Estado amplie o acesso à cultura.', 'Tipo assim, o governo tem que fazer alguma coisa, né?', 'Vc sabe q a cultura é mto importante p/ todos.', 'A galera precisa curtir mais cinema e teatro.'], 0),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('Toda língua varia conforme o lugar, o grupo social, a época e a situação.', True),
         ('O português falado no Nordeste é errado.', False),
         ('A norma-padrão é a variedade exigida em documentos oficiais e na redação do ENEM.', True),
         ('Usar gírias em uma conversa entre amigos é adequado.', True),
         ('A linguagem formal é adequada a qualquer situação, inclusive entre amigos íntimos.', False)]),
     C('Associe o tipo de variação ao exemplo:',
       [('regional', '“bergamota”, “tangerina” e “mexerica” para a mesma fruta'), ('histórica', '“pharmacia” passou a ser escrita “farmácia”'),
        ('social', 'gírias usadas por um grupo de jovens'), ('situacional', 'falar de um jeito na entrevista e de outro em casa')]),
     A('Reescreva em registro formal: “E aí, galera, a parada é a seguinte: o passeio foi cancelado, beleza?”',
       'Ex.: Prezados alunos, informamos que o passeio foi cancelado.', 2),
     A('Escreva uma frase informal e uma formal para pedir a alguém que feche a porta.',
       'Resposta pessoal. Ex.: Informal: “Fecha a porta aí, por favor?” Formal: “O senhor poderia, por gentileza, fechar a porta?”', 2),
  ],
  producao='Imagine que você vai faltar a um compromisso amanhã. Escreva duas mensagens sobre o mesmo assunto: uma informal, para um amigo (3 ou 4 linhas), e uma formal, para a direção da escola ou para um chefe (4 a 6 linhas). Depois, sublinhe em cada uma duas marcas do registro que você usou.')

E(40, B, 'Linguagem figurada na leitura: denotação, conotação e figuras de linguagem',
  aquecimento='O que significa dizer que alguém “tem um coração de pedra”? E “estou morrendo de fome”? Quem fala isso está falando de uma pedra de verdade ou morrendo de verdade?',
  quadro=['# Denotação x conotação',
    '- Denotação: sentido literal, o do dicionário. Ex.: “A pedra rolou da montanha.”',
    '- Conotação: sentido figurado, que depende do contexto. Ex.: “Ele tem um coração de pedra.” (é insensível)',
    '- A conotação é comum em poemas, letras de música, propagandas, charges e na fala do dia a dia.',
    '# Figuras de linguagem: recursos que criam efeitos de sentido',
    '- Comparação: aproxima dois elementos com conectivo (como, tal qual, feito, parece). Ex.: “Seus olhos brilhavam como estrelas.”',
    '- Metáfora: comparação sem conectivo; um termo assume o sentido de outro. Ex.: “Seus olhos são duas estrelas.” / “Meu quarto é um forno.”',
    '- Metonímia: troca de um termo por outro com que tem relação próxima. Ex.: “Li Machado de Assis.” (autor pela obra) / “Bebi dois copos.” (recipiente pelo conteúdo)',
    '- Hipérbole: exagero intencional. Ex.: “Já falei isso mil vezes!” / “Estou morrendo de rir.”',
    '- Ironia: dizer o contrário do que se pensa, com intenção crítica ou de humor. Ex.: “Que belo trabalho!” (diante de um trabalho malfeito)',
    '- Personificação (prosopopeia): dá características humanas a seres não humanos. Ex.: “O vento sussurrava na janela.”',
    '- Antítese: aproxima palavras de sentidos opostos. Ex.: “Entre o riso e o choro, a vida segue.”',
    '- Eufemismo: suaviza uma ideia desagradável. Ex.: “Ele partiu desta para melhor.” (morreu) / “Ele faltou com a verdade.” (mentiu)',
    '# Para que servem na leitura',
    '- Em poemas: criam imagens, emoção e musicalidade.',
    '- Em propagandas: chamam a atenção e ajudam a convencer. Ex.: “Este sorvete é um pedaço do paraíso.” (metáfora e hipérbole)',
    '- No dia a dia: deixam a fala mais expressiva. Ex.: “O ônibus estava uma lata de sardinha.”',
    '# Mais exemplos',
    '- Paradoxo: ideias opostas que parecem impossíveis juntas. Ex.: “Amor é fogo que arde sem se ver” (Camões).',
    '- Catacrese: metáfora que já se tornou comum na língua. Ex.: pé da mesa, braço da cadeira, céu da boca.',
    '# Fique atento',
    '- Comparação tem conectivo (como, feito, parece); metáfora não tem.',
    '- Na metonímia há uma relação real entre os termos (autor e obra, parte e todo). Ex.: “Há muitas bocas para alimentar.” (bocas = pessoas)',
    '- A ironia depende do contexto: a mesma frase pode ser elogio ou crítica.',
    '- Nas provas, pergunte sempre: qual EFEITO de sentido a figura produz (exagero, suavização, crítica, emoção)?'],
  q=[M('Em qual frase a palavra em maiúsculas está em sentido DENOTATIVO (literal)?',
       ['O GELO derreteu dentro do copo.', 'Ela me deu um GELO depois da briga.', 'Aquele olhar era puro GELO.', 'Ele tem sangue de GELO nas veias.'], 0),
     M('“Ele tem um coração de ouro” significa que ele:',
       ['é muito bondoso', 'é muito rico', 'tem um problema no coração', 'trabalha vendendo joias'], 0),
     A('Explique a diferença entre denotação e conotação.',
       'Denotação é o sentido literal, do dicionário; conotação é o sentido figurado, que depende do contexto.', 2),
     T('A cidade dorme de olhos acesos: / cada janela é uma estrela cansada. / O vento corre pelas ruas vazias / como um menino atrasado para a escola. / No ponto, um homem espera o último ônibus / há mil anos. / Entre o silêncio e a buzina, / a noite boceja e vira madrugada.',
       fonte='Poema elaborado para esta atividade. A barra (/) separa os versos.', titulo='Noturno', para=4),
     M('No verso “cada janela é uma estrela cansada”, há uma:',
       ['metáfora', 'comparação', 'metonímia', 'antítese'], 0),
     M('Nos versos “O vento corre pelas ruas vazias / como um menino atrasado para a escola”, a comparação é marcada pela palavra:',
       ['como', 'vento', 'vazias', 'atrasado'], 0),
     M('Em “um homem espera o último ônibus / há mil anos”, o exagero (hipérbole) expressa:',
       ['a sensação de que a espera é longa e cansativa', 'a idade exata do homem que espera', 'a pontualidade do transporte da cidade', 'a alegria de quem chega cedo ao ponto'], 0),
     A('Copie do poema um exemplo de personificação e um exemplo de antítese.',
       'Personificação: “A cidade dorme de olhos acesos”, “a noite boceja” ou “estrela cansada”. Antítese: “Entre o silêncio e a buzina”.', 2),
     T('Anúncio de uma marca fictícia de colchões. Na imagem, uma pessoa dorme sorrindo sobre uma nuvem branca, no céu azul. Abaixo, o texto: “Colchão Nuvem: durma nas alturas. Com ele, o despertador vai ter que implorar para você acordar.”',
       fonte='Anúncio descrito em palavras, elaborado para esta atividade.', titulo='Colchão Nuvem', para=3),
     M('A imagem da pessoa dormindo sobre uma nuvem sugere, de forma conotativa, que o colchão é:',
       ['macio e confortável', 'feito de algodão e de água', 'perigoso para quem tem medo de altura', 'barato e fácil de carregar'], 0),
     M('Em “o despertador vai ter que implorar para você acordar”, há personificação porque:',
       ['um objeto recebe uma ação própria de seres humanos', 'uma ideia desagradável é suavizada', 'duas palavras de sentidos opostos são aproximadas', 'o nome do autor é usado no lugar da obra'], 0),
     M('O principal efeito da linguagem figurada nesse anúncio é:',
       ['tornar a mensagem expressiva e persuadir o leitor a comprar o colchão', 'informar com precisão as medidas e o preço do colchão', 'criticar quem dorme demais e chega atrasado', 'ensinar o leitor a montar e limpar o colchão'], 0),
     M('“Que lindo! Você chegou só duas horas atrasado.” Essa frase é um exemplo de:',
       ['ironia', 'eufemismo', 'antítese', 'metonímia'], 0),
     M('Qual frase apresenta ANTÍTESE?',
       ['Nasceu pobre e morreu rico.', 'O mar é um espelho azul.', 'Esperei por você um século.', 'O sino chorava na torre.'], 0),
     M('Na frase “O funcionário foi convidado a deixar a empresa” (em vez de “foi demitido”), há:',
       ['eufemismo, que suaviza uma informação desagradável', 'hipérbole, que exagera a informação', 'antítese, que aproxima ideias opostas', 'comparação, marcada pelo conectivo “como”'], 0),
     C('Associe cada frase à figura de linguagem:',
       [('“Estou morrendo de fome.”', 'hipérbole'), ('“As estrelas dançavam no céu.”', 'personificação'), ('“Ele é lento como uma tartaruga.”', 'comparação'),
        ('“Ela descansou em paz.” (= morreu)', 'eufemismo'), ('“A escola inteira aplaudiu a apresentação.”', 'metonímia')]),
     VF('Marque V (verdadeiro) ou F (falso):',
        [('A metáfora é uma comparação sem conectivo.', True),
         ('Na denotação, a palavra é usada em sentido figurado.', False),
         ('“Morrer de rir” é uma hipérbole.', True),
         ('A ironia diz exatamente o que a pessoa pensa, sem segundas intenções.', False),
         ('Propagandas usam a linguagem figurada para chamar a atenção e convencer.', True)]),
     A('Transforme a comparação em metáfora: “Minha mãe é forte como uma rocha.”', 'Minha mãe é uma rocha.'),
     A('Escreva uma frase em que a palavra “luz” tenha sentido conotativo (figurado).',
       'Resposta pessoal. Ex.: “Você é a luz da minha vida.” / “Aquela professora foi uma luz no meu caminho.”'),
  ],
  producao='Escreva um poema curto (6 a 10 versos) ou um parágrafo descritivo sobre a sua cidade ou o seu bairro, usando pelo menos quatro figuras de linguagem diferentes (por exemplo: metáfora, comparação, personificação e hipérbole). Depois, indique entre parênteses o nome de cada figura usada.')
